% 2026 revival styling (draft-mode rendering only, not historical): the
% original \note was a bare \textwidth framebox dropped mid-paragraph — it
% overflowed the right page edge, could not break across pages, and was
% typographically indistinguishable from normative spec content. Re-set the
% authors' editorial annotations so they read as manuscript notes: small
% sans-serif on a tinted ground with a heavy colored left bar and a
% small-caps "Draft note" label; mdframed lets long notes break over pages.
\usepackage{mdframed}
\definecolor{draftnotebar}{rgb}{0.72,0.29,0.11}
\definecolor{draftnotebg}{rgb}{0.975,0.949,0.914}
\newmdenv[
  backgroundcolor=draftnotebg,
  linecolor=draftnotebar,
  topline=false,bottomline=false,rightline=false,
  linewidth=2.5pt,
  innerleftmargin=8pt,innerrightmargin=8pt,
  innertopmargin=6pt,innerbottommargin=6pt,
  skipabove=8pt,skipbelow=8pt
]{draftnotebox}
\newcommand{\note}[1]{%
\begin{draftnotebox}%
{\sffamily\footnotesize\color{draftnotebar}\textsc{Draft note}}\\[2pt]
{\sffamily\small #1}%
\end{draftnotebox}}
